import {notFound} from "next/navigation";import Link from "next/link";import {servicePages} from "@/data/servicePages";
export default async function Page({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const s=servicePages.find(x=>x.slug===slug);if(!s)notFound();return <>
<section className="servicePhotoHero" style={{backgroundImage:`linear-gradient(90deg,rgba(4,30,49,.91),rgba(4,30,49,.42)),url("${s.image}")`}}><div className="wrap"><div className="kicker">Serviços</div><h1>{s.title}</h1><p>{s.intro}</p></div></section>
<section className="section"><div className="wrap serviceEditorial"><div className="serviceIntroImage"><img src={s.image} alt={s.title}/></div><div><div className="kicker">Competências</div><h2 className="title">Os nossos serviços incluem</h2><div className="serviceRows">{s.items.map(([a,b],i)=><div className="serviceRow" key={a}><span>{String(i+1).padStart(2,"0")}</span><div><h3>{a}</h3><p>{b}</p></div></div>)}</div></div></div></section>
<section className="section serviceWhy"><div className="wrap"><div className="kicker">Porquê escolher-nos</div><h2 className="title">Qualidade, segurança e acompanhamento</h2><div className="whyGrid">{s.why.map(([a,b])=><div className="whyCard" key={a}><h3>{a}</h3><p>{b}</p></div>)}</div><div className="serviceCTA"><div><h2>Tem um projeto nesta área?</h2><p>Fale connosco para analisarmos as necessidades do seu projeto.</p></div><Link href="/pedir-proposta" className="button">Pedir proposta</Link></div></div></section></>}